const KAMPANYA_MODU = process.env.KAMPANYA_MODU === 'true';

export function indirimliFiyat(fiyat, yuzde) {
  if (KAMPANYA_MODU) {
    // Kampanya döneminde indirimin yarısı uygulanır
    return fiyat - (fiyat * (yuzde / 2) / 100);
  } else {
    // Normal indirim
    return fiyat - (fiyat * yuzde / 100);
  }
}"}

